+///|
+fn Progress::learn_event(self : Progress, event : Json, line : String) -> Unit {
+  if event != Json::null() {
+    let protected_values : DiagnosticProtectedValues = {
+      secrets: [],
+      visited: 0,
+      incomplete: false,
+    }
+    diagnostic_protected_values(event, protected_values, line, false)
+    if protected_values.incomplete ||
+      self.secrets.length() + protected_values.secrets.length() > 1024 {
+      self.protection_incomplete = true
+      self.details_truncated = true
+      self.recent.clear()
+      self.failures.clear()
+      self.unrecognized.clear()
+      self.stderr_lines.clear()
+    } else {
+      for secret in protected_values.secrets {
+        add_protected_secret(self.secrets, secret)
+      }
+      self.secrets.sort_by((a, b) => b.length().compare(a.length()))
+    }
+  }
+}
