1278	///|
1279	priv struct DiagnosticProtectedValues {
1280	  secrets : Array[String]
1281	  mut visited : Int32
1282	  mut incomplete : Bool
1283	}
1284	
1285	///|
1286	fn diagnostic_add_protected(
1287	  value : String,
1288	  output : String,
1289	  uncertain : Bool,
1290	  destination : Array[String],
1291	  result : DiagnosticProtectedValues,
1292	) -> Unit {
1293	  if value == "" ||
1294	    (
1295	      !output.contains(value) &&
1296	      (!uncertain || diagnostic_partial_secret(output, [value]) == output)
1297	    ) {
1298	    return
1299	  }
1300	  if result.secrets.length() >= 512 {
1301	    result.incomplete = true
1302	    return
1303	  }
1304	  destination.push(value)
1305	}
