1307	///|
1308	fn diagnostic_protected_values(
1309	  value : Json,
1310	  result : DiagnosticProtectedValues,
1311	  output : String,
1312	  uncertain : Bool,
1313	  secret~ : Bool = false,
1314	  depth~ : Int32 = 0,
1315	) -> Unit {
1316	  if result.visited >= 65536 || depth >= 64 {
1317	    result.incomplete = true
1318	    return
1319	  }
1320	  result.visited += 1
1321	  match value {
1322	    Json::String(text) if text != "" && secret => {
1323	      let destination = result.secrets
1324	      diagnostic_add_protected(text, output, uncertain, destination, result)
1325	      for line in text.replace_all(old="\r", new="\n").split("\n") {
1326	        if line != "" && line.length() < text.length() {
1327	          diagnostic_add_protected(
1328	            line.to_owned(),
1329	            output,
1330	            uncertain,
1331	            destination,
1332	            result,
1333	          )
1334	        }
1335	        for word in line.split(" ") {
1336	          for part in word.split("=") {
1337	            if part != "" && part.length() < text.length() {
1338	              diagnostic_add_protected(
1339	                part.to_owned(),
1340	                output,
1341	                uncertain,
1342	                destination,
1343	                result,
1344	              )
1345	            }
1346	          }
1347	        }
1348	      }
1349	      let escaped = Json::string(text).stringify()
1350	      if escaped.length() > 2 {
1351	        let encoded = escaped[1:escaped.length() - 1].to_owned()
1352	        if encoded != text {
1353	          diagnostic_add_protected(
1354	            encoded, output, uncertain, destination, result,
1355	          )
1356	        }
1357	      }
1358	    }
1359	    Json::String(text) if text != "" => {
1360	      let mut next_secret = false
1361	      for word in text.split(" ") {
1362	        let word = word.to_owned()
1363	        if next_secret {
1364	          diagnostic_add_protected(
1365	            word,
1366	            output,
1367	            uncertain,
1368	            result.secrets,
1369	            result,
1370	          )
1371	          next_secret = false
1372	        } else if word.split_once("=") is Some((name, value)) {
1373	          if credential_field(name.to_owned(), for_diagnostics=true) {
1374	            diagnostic_add_protected(
1375	              value.to_owned(),
1376	              output,
1377	              uncertain,
1378	              result.secrets,
1379	              result,
1380	            )
1381	          }
1382	        } else if word.has_prefix("-") &&
1383	          credential_field(word, for_diagnostics=true) {
1384	          next_secret = true
1385	        }
1386	      }
1387	    }
1388	    Json::Array(values) =>
1389	      for item in values {
1390	        diagnostic_protected_values(
1391	          item,
1392	          result,
1393	          output,
1394	          uncertain,
1395	          secret~,
1396	          depth=depth + 1,
1397	        )
1398	      }
1399	    Json::Object(values) =>
1400	      for name, item in values {
1401	        let key = name.to_lower().replace_all(old="_", new="")
1402	        diagnostic_protected_values(
1403	          item,
1404	          result,
1405	          output,
1406	          uncertain,
1407	          secret=secret ||
1408	            credential_field(name, for_diagnostics=true) ||
1409	            key == "pairingcode",
1410	          depth=depth + 1,
1411	        )
1412	      }
1413	    _ => ()
1414	  }
1415	}
