1417	///|
1418	fn diagnostic_output(
1419	  output : Bytes,
1420	  environment : Map[String, String],
1421	  protected_input? : String,
1422	  protect_all_input~ : Bool = false,
1423	  protected_secrets? : Array[String],
1424	  omitted~ : Bool = false,
1425	) -> String? {
1426	  if output.length() == 0 {
1427	    return if omitted {
1428	      Some("[error details incomplete or truncated]")
1429	    } else {
1430	      None
1431	    }
1432	  }
1433	  let limit = if output.length() > 8192 { 8192 } else { output.length() }
1434	  let incomplete = omitted || limit < output.length()
1435	  let text = @utf8.decode_lossy(output[:limit])
1436	  let safeguards : DiagnosticProtectedValues = {
1437	    secrets: [],
1438	    visited: 0,
1439	    incomplete: false,
1440	  }
1441	  if protected_input is Some(input) {
1442	    diagnostic_protected_values(
1443	      @json.parse(input),
1444	      safeguards,
1445	      text,
1446	      incomplete,
1447	      secret=protect_all_input,
1448	    ) catch {
1449	      _ => safeguards.incomplete = true
1450	    }
1451	  }
1452	  if safeguards.incomplete {
1453	    return Some(
1454	      "Error output omitted because protected input could not be fully matched\n[error details incomplete or truncated]",
1455	    )
1456	  }
1457	  Some(
1458	    diagnostic_text(
1459	      text,
1460	      environment~,
1461	      omitted=incomplete,
1462	      protected_secrets=safeguards.secrets + protected_secrets.unwrap_or([]),
1463	      incomplete_final_line=incomplete && output[limit - 1] != b'\n',
1464	    ),
1465	  )
1466	}
