1498	///|
1499	async fn DiagnosticCapture::read(
1500	  self : DiagnosticCapture,
1501	  reader : @process.ReadFromProcess,
1502	) -> Unit {
1503	  try {
1504	    while reader.read_some(max_len=4096) is Some(chunk) {
1505	      let remaining = self.limit - self.output.length()
1506	      let count = if chunk.length() < remaining {
1507	        chunk.length()
1508	      } else {
1509	        remaining
1510	      }
1511	      if count > 0 {
1512	        self.output.write_bytes(chunk[:count])
1513	      }
1514	      if count < chunk.length() {
1515	        self.truncated = true
1516	      }
1517	    }
1518	  } catch {
1519	    error =>
1520	      if @async.is_being_cancelled() {
1521	        raise error
1522	      } else {
1523	        self.truncated = true
1524	      }
1525	  }
1526	  self.finished = true
1527	}
1528	
1529	///|
1530	async fn wait_diagnostic_captures(captures : Array[DiagnosticCapture]) -> Unit {
1531	  @async.with_timeout(250, async fn() {
1532	    while captures.iter().any(capture => !capture.finished) {
1533	      @async.sleep(5)
1534	    }
1535	  }) catch {
1536	    error => if @async.is_being_cancelled() { raise error }
1537	  }
1538	}
