1540	///|
1541	async fn diagnostic_process_output(
1542	  program : String,
1543	  args : Array[String],
1544	  environment~ : Map[String, String],
1545	  cwd? : StringView,
1546	  stdin? : &@process.ProcessInput,
1547	  stdout_limit~ : Int32,
1548	  stderr_limit~ : Int32,
1549	  stderr_capture? : DiagnosticCapture,
1550	) -> (Int32, Bytes, Bool, Bytes, Bool) {
1551	  let (out, stdout) = @process.read_from_process()
1552	  defer out.close()
1553	  let (err, stderr) = @process.read_from_process()
1554	  defer err.close()
1555	  @async.with_task_group(async fn(group) {
1556	    let child = @process.spawn(
1557	      group,
1558	      program,
1559	      args,
1560	      extra_env=environment,
1561	      inherit_env=false,
1562	      cwd?,
1563	      stdin?,
1564	      stdout~,
1565	      stderr~,
1566	    )
1567	    let output = DiagnosticCapture::new(stdout_limit)
1568	    let errors = stderr_capture.unwrap_or(DiagnosticCapture::new(stderr_limit))
1569	    group.spawn_bg(no_wait=true, async fn() { output.read(out) })
1570	    group.spawn_bg(no_wait=true, async fn() { errors.read(err) })
1571	    let status = child.wait()
1572	    if status == 0 {
1573	      while !output.finished {
1574	        @async.sleep(5)
1575	      }
1576	      wait_diagnostic_captures([errors])
1577	    } else {
1578	      wait_diagnostic_captures([output, errors])
1579	    }
1580	    (
1581	      status,
1582	      output.output.to_bytes(),
1583	      output.truncated || !output.finished,
1584	      errors.output.to_bytes(),
1585	      errors.truncated || !errors.finished,
1586	    )
1587	  })
1588	}
