 45	  let clock = @env.now() / 1000UL % 86400UL
 46	  let pad = fn(value : UInt64) {
 47	    if value < 10UL {
 48	      "0" + value.to_string()
 49	    } else {
 50	      value.to_string()
 51	    }
 52	  }
 53	  progress_write(
 54	    pad(clock / 3600UL) +
 55	    ":" +
 56	    pad(clock / 60UL % 60UL) +
 57	    ":" +
 58	    pad(clock % 60UL) +
 59	    " " +
