175	  protection_incomplete~ : Bool = false,
176	) -> Progress {
177	  let secrets = []
178	  for name, value in environment.unwrap_or(@env.get_env_vars()) {
179	    if sensitive_name(name) && value != "" {
180	      // Multiline credentials must also be masked in line-oriented output.
181	      add_protected_secret(secrets, value)
182	    }
183	  }
184	  if protected_secrets is Some(values) {
185	    for value in values {
186	      add_protected_secret(secrets, value)
187	    }
188	  }
189	  for value in create_recording.protected_secrets {
190	    add_protected_secret(secrets, value)
191	  }
192	  secrets.sort_by((a, b) => b.length().compare(a.length()))
193	  {
194	    stage,
195	    operations: {},
196	    builds: {},
197	    secrets,
198	    protection_incomplete: protection_incomplete ||
199	    create_recording.protection_incomplete,
200	    recording: recording_override.unwrap_or(
201	      environment.unwrap_or(@env.get_env_vars()).get("ORCA_ENV_DEVSY_RECORDING") !=
202	      Some("0"),
203	    ),
204	    context,
205	    phase_count: 0,
206	    private_key: false,
207	    classic_build: false,
208	    recent: [],
209	    failures: [],
210	    unrecognized: [],
211	    stderr_lines: [],
212	    details_truncated: false,
213	  }
214	}
