544	fn progress_normalize_json(
545	  value : Json,
546	  truncated : Ref[Bool],
547	  depth : Int32,
548	) -> Json {
549	  if depth >= 64 {
550	    truncated.val = true
551	    return Json::string("[unavailable]")
552	  }
553	  match value {
554	    Json::String(text) => Json::string(progress_json_text(text, truncated))
555	    Json::Array(values) =>
556	      Json::array(
557	        values.map(item => progress_normalize_json(item, truncated, depth + 1)),
558	      )
559	    Json::Object(values) => {
560	      let result = Json::empty_object()
561	      for name, item in values {
562	        let key = progress_json_text(name, truncated)
563	        if field(result, key) is Some(_) {
564	          truncated.val = true
565	        } else {
566	          set_field(
567	            result,
568	            key,
569	            progress_normalize_json(item, truncated, depth + 1),
570	          )
571	        }
572	      }
573	      result
574	    }
575	    _ => value
576	  }
