676	              emit=messages || statuses,
677	            )
678	          _ => {
679	            let truncated : Ref[Bool] = { val: false, }
680	            let safe = diagnostic_json(warning, {}, self.secrets, truncated, 0).stringify()
681	            if truncated.val {
682	              self.details_truncated = true
683	            }
684	            self.message(safe, debug=false, warning=true, emit=false)
685	          }
686	        }
687	      }
688	    }
689	    if field(event, "outcome") != Some(Json::string("success")) &&
690	      (
691	        field(event, "error") is Some(_) ||
692	        field(event, "message") is Some(_) ||
693	        field(event, "code") is Some(_) ||
694	        field(event, "outcome") == Some(Json::string("failure")) ||
695	        field(event, "outcome") == Some(Json::string("error"))
696	      ) {
697	      self.remember_unrecognized_json(event)
698	    }
699	    return
700	  }
701	  if field(event, "kind") == Some(Json::string("orca-env-devsy-server-exit")) {
702	    return
703	  }
704	  if event is Json::Object(_) {
705	    let kind = field(event, "kind")
706	    guard kind == None ||
707	      kind == Some(Json::string("log")) ||
708	      kind == Some(Json::string("error")) else {
709	      self.remember_unrecognized_json(event)
710	      return
711	    }
712	    let message = match field(event, "msg") {
713	      Some(value) => Some(value)
714	      None =>
715	        match field(event, "message") {
716	          Some(value) => Some(value)
717	          None =>
718	            match field(event, "error") {
719	              Some(Json::Object(_) as value) => field(value, "message")
720	              value => value
721	            }
722	        }
723	    }
724	    guard message is Some(Json::String(text)) else {
725	      self.remember_unrecognized_json(event)
726	      return
727	    }
728	    let level = field(event, "level")
729	    self.message(
730	      text,
731	      debug=level == Some(Json::string("debug")) ||
732	        level == Some(Json::string("trace")),
733	      warning=kind == Some(Json::string("error")) ||
734	        level == Some(Json::string("warn")) ||
735	        level == Some(Json::string("error")),
736	      emit=messages || (statuses && kind != None),
737	    )
738	  } else {
739	    if event != Json::null() {
740	      self.remember_unrecognized_json(event)
741	      return
742	    }
743	    // Malformed JSON and binary output are not a safe free-text fallback.
744	    let text = line.trim().to_owned()
745	    if text.has_prefix("[ERROR]") || text.has_prefix("[WARN]") {
746	      self.message(text, debug=false, warning=true, emit=messages)
747	      return
748	    }
749	    if text.has_prefix("{") || text.has_prefix("[") {
750	      self.details_truncated = true
751	      self.remember_unrecognized(text)
752	      return
753	    }
754	    self.message(
755	      text,
756	      debug=text.contains(" DEBUG ") ||
757	        text.contains(" TRACE ") ||
758	        text.has_prefix("DEBUG ") ||
759	        text.has_prefix("TRACE "),
760	      warning=text.contains(" WARN ") ||
761	        text.contains(" ERROR ") ||
762	        text.has_prefix("WARN ") ||
763	        text.has_prefix("ERROR "),
764	      emit=messages,
765	    )
766	  }
767	}
