382	  let key = ["pipeline", "operationId", "phase", "step"]
383	    .map(name => field(event, name).unwrap_or(Json::null()).stringify())
384	    .join(":")
385	  if state == "started" {
386	    if self.operations.length() >= 256 {
387	      self.operations.clear()
388	    }
389	    self.operations.set(key, @env.now())
390	    progress_message(label + ": running…")
391	  } else {
392	    let duration = match field(event, "durationMs") {
393	      Some(Json::Number(value, ..)) if value >= 0 && value < 864000000 =>
394	        Some(seconds(value.to_uint64()))
395	      _ => self.operations.get(key).map(start => seconds(@env.now() - start))
396	    }
397	    self.operations.remove(key)
398	    let timing = duration.map(value => value + ", ").unwrap_or("") +
399	      "elapsed " +
400	      seconds(@env.now() - progress_started)
401	    progress_message(
402	      label +
403	      ": " +
404	      (if state == "succeeded" { "done" } else { state }) +
405	      " (" +
406	      timing +
407	      ")",
408	    )
409	  }
410	}
