412	///|
413	fn classic_build_step(text : String) -> Bool {
414	  guard text.has_prefix("Step ") &&
415	    text[5:].split_once("/") is Some((step, rest)) &&
416	    rest.split_once(" ") is Some((total, detail)) else {
417	    return false
418	  }
419	  step.length() > 0 &&
420	  total.length() > 0 &&
421	  step.iter().all(c => c >= '0' && c <= '9') &&
422	  total.iter().all(c => c >= '0' && c <= '9') &&
423	  detail.trim().has_prefix(":")
424	}
