426	///|
427	async fn Progress::message(
428	  self : Progress,
429	  text : String,
430	  debug~ : Bool,
431	  warning~ : Bool,
432	  emit~ : Bool = true,
433	) -> Unit {
434	  if self.protection_incomplete {
435	    self.details_truncated = true
436	    self.remember(
437	      "error detail unavailable because workspace protection values could not be read",
438	      warning=true,
439	    )
440	    return
441	  }
442	  for line in text.split("\n") {
443	    let text = line.trim().to_owned()
444	    if text == "" {
445	      continue
446	    }
447	    guard self.safe_message(text) is Some(safe) else {
448	      self.details_truncated = true
449	      continue
450	    }
451	    if !debug || warning {
452	      self.remember(safe, warning~)
453	    }
454	    if !emit {
455	      continue
456	    }
457	    if safe.has_prefix("#") {
458	      guard safe.split_once(" ") is Some((id, rest)) &&
459	        id.length() > 1 &&
460	        id[1:].iter().all(c => c >= '0' && c <= '9') else {
461	        continue
462	      }
463	      let detail = rest.trim().to_owned()
464	      guard detail.has_prefix("[") ||
465	        detail.has_prefix("DONE") ||
466	        detail.has_prefix("ERROR") ||
467	        detail.has_prefix("CACHED") else {
468	        continue
469	      }
470	      if detail.has_prefix("ERROR") && debug && !warning {
471	        self.remember(safe, warning=true)
472	      }
473	      if self.builds.get(id.to_owned()) == Some(detail) {
474	        continue
475	      }
476	      if self.builds.length() < 2048 || self.builds.contains(id.to_owned()) {
477	        self.builds.set(id.to_owned(), detail)
478	      }
479	      progress_message("Build " + id.to_owned() + ": " + detail)
480	    } else if classic_build_step(safe) {
481	      // Classic RUN output has no prefix. Only its own completion marker
482	      // ends this mode; phase events on another pipe can arrive ahead of it.
483	      self.classic_build = true
484	      progress_message("Build " + safe)
485	    } else if safe.has_prefix("Successfully built ") ||
486	      safe.has_prefix("Successfully tagged ") {
487	      self.classic_build = false
488	      progress_message("Build: " + safe)
489	    } else if self.classic_build && !warning {
490	      continue
491	    } else if !debug && !safe.has_prefix("{") && !safe.has_prefix("[") {
492	      progress_message(self.stage + ": " + safe)
493	    } else if !debug && safe.has_prefix("[credential") {
494	      progress_message(self.stage + ": " + safe)
495	    }
496	  }
497	}
498	
499	///|
882	  if oversized && scanner is Some(current) {
883	    current.feed(@utf8.decode_lossy(pending.to_bytes()))
884	    private_key.val = current.finish()
885	  } else if pending.length() > 0 {
886	    let malformed : Ref[Bool] = { val: false, }
887	    let line = @utf8.decode(pending.to_bytes()) catch {
888	      _ => {
889	        self.details_truncated = true
890	        malformed.val = true
891	        @utf8.decode_lossy(pending.to_bytes())
892	      }
893	    }
894	    let masked = diagnostic_partial_secret(line, self.secrets)
895	    if masked != line {
896	      self.details_truncated = true
897	    }
898	    if malformed.val {
899	      let current = PrivateKeyScanner::new(private_key.val)
900	      current.feed(masked)
901	      private_key.val = current.finish()
902	    } else if self.filter_output_line(masked, private_key) is Some(safe) {
903	      if !capture && !raw_messages {
904	        self.remember_stderr(safe)
905	      }
906	      if raw_messages {
907	        self.message(safe, debug=false, warning=true, emit=false)
908	      } else if capture {
909	        self.line(safe, statuses~, messages~)
910	      } else {
911	        self.stderr_line(safe, statuses~, messages~)
912	      }
913	    }
914	  }
915	  if capture {
916	    @utf8.decode(output.to_bytes())
917	  } else {
918	    tail
919	  }
920	}

