1343	async fn lifecycle_state(mode : String) -> (Json, Json) {
1344	  let input = @stdio.stdin.read_all()
1345	  let payload = @json.parse(input.text())
1346	  guard field(payload, "schemaVersion") == Some(Json::number(1)) else {
1347	    raise AdapterError("Invalid lifecycle payload schema")
1348	  }
1349	  let result = match field(payload, "recipeResult") {
1350	    Some(value) => value
1351	    None => raise AdapterError("Missing recipeResult")
1352	  }
1353	  let state = match field(result, "userData") {
1354	    Some(value) => value
1355	    None => raise AdapterError("Missing saved adapter state")
1356	  }
1357	  guard field(state, "adapterVersion") == Some(Json::number(1)) else {
1358	    raise AdapterError("Unsupported adapter state")
1359	  }
1360	  validate_state(state)
1361	  match workspace(state) {
1362	    Some(current) if field(current, "uid") == field(state, "workspaceUid") => ()
1363	    None if mode == "destroy" => ()
1364	    _ => raise AdapterError("Workspace missing or replaced")
1365	  }
1366	  (state, result)
1367	}
