1432	///|
1433	async fn execute_inner(mode : String) -> Unit {
1434	  notify(mode)
1435	  if mode == "create" ||
1436	    mode == "resume" ||
1437	    mode == "recover" ||
1438	    mode == "restart" {
1439	    save_diagnostic(
1440	      "connection-budget",
1441	      "selected",
1442	      timeout_ms=connection_timeout_ms(),
1443	    )
1444	  }
1445	  let started = @env.now()
1446	  let (state, previous, deadline) = if mode == "create" {
1447	    let (state, expires) = create_state()
1448	    (state, Json::null(), Some(expires))
1449	  } else {
1450	    let (state, previous) = if mode == "recover" || mode == "restart" {
1451	      connection_timeout(started + connection_timeout_ms().to_uint64(), async fn() {
1452	        lifecycle_state(mode)
1453	      })
1454	    } else {
1455	      lifecycle_state(mode)
1456	    }
1457	    (
1458	      state,
1459	      previous,
1460	      if mode == "recover" || mode == "restart" {
1461	        Some(started + connection_timeout_ms().to_uint64())
1462	      } else {
1463	        None
1464	      },
1465	    )
1466	  }
1467	  let operation = if mode == "resume" || mode == "suspend" || mode == "destroy" {
1468	    Some(connection_operation_lock(state))
1469	  } else {
1470	    None
1471	  }
1472	  defer (if operation is Some(lock) { lock.close() })
1473	  if mode == "resume" {
1474	    guard workspace(state) is Some(current) &&
1475	      field(current, "uid") == field(state, "workspaceUid") else {
1476	      raise AdapterError("Workspace missing or replaced before resume")
1477	    }
1478	    unpause_tunnel(state)
1479	  }
1480	  match mode {
1481	    "create" => {
1482	      create_recording.phase = "connection"
1483	      errdefer discard_created_workspace(state)
1484	      connection_timeout(deadline.unwrap(), async fn() {
1485	        codex_addon(state)
1486	        emit_connection(state, true, deadline?)
1487	      })
1488	    }
1489	    "resume" => {
1490	      ignore(
1491	        devsy(
1492	          state,
1493	          [
1494	            "--result-format",
1495	            "json",
1496	            "workspace",
1497	            "up",
1498	            required(state, "workspaceId"),
1499	            "--ide-launch",
1500	            "skip",
1501	          ] +
1502	          orca_storage_args(state),
1503	          "workspace-resume",
1504	        ),
1505	      )
1506	      let expires = connection_deadline()
1507	      idle_reset(state, "workspace_resumed")
1508	      connection_timeout(expires, async fn() {
1509	        let port = if required(state, "connection") == "orca-server" {
1510	          Some(reserve_server_port(state))
1511	        } else {
1512	          None
1513	        }
1514	        ensure_ssh_worker(state, port, deadline=expires)
1515	        codex_addon(state)
1516	        if required(state, "connection") == "orca-server" {
1517	          ignore(recover_server(state))
1518	        }
1519	        emit_connection(state, false, existing=previous, deadline=expires)
1520	      })
1521	    }
1522	    "recover" | "restart" => {
1523	      recover_connection(state, restart=mode == "restart", deadline?)
1524	      let connection = field(previous, "connection").unwrap()
1525	      write_connection(state, connection)
1526	    }
1527	    "suspend" => {
1528	      pause_tunnel(state)
1529	      defer unpause_tunnel(state)
1530	      stop_workspace(state)
1531	    }
1532	    "destroy" => {
1533	      pause_tunnel(state)
1534	      errdefer unpause_tunnel(state)
1535	      ignore(
1536	        devsy(
1537	          state,
1538	          [
1539	            "workspace",
1540	            "delete",
1541	            required(state, "workspaceId"),
1542	            "--ignore-not-found",
1543	          ],
1544	          "workspace-delete",
1545	        ),
1546	      )
1547	      cleanup_orca_volume(state)
1548	      if field(state, "tunnelDirectory") is Some(Json::String(directory)) {
1549	        for name in ["server-update-pending", "server-update-complete"] {
1550	          if @fs.exists(directory + "/" + name) {
1551	            @fs.remove(directory + "/" + name)
1552	          }
1553	        }
1554	      }
1555	      close_tunnel(state)
1556	    }
1557	    _ => raise AdapterError("Unknown command")
1558	  }
1559	  save_diagnostic(mode, "success")
1560	  progress_message(mode + ": done (" + progress_timing(progress_started) + ")")
1561	}

