1488	///|
1489	fn DiagnosticCapture::new(limit : Int32) -> DiagnosticCapture {
1490	  {
1491	    output: @buffer.Buffer(size_hint=if limit < 4096 { limit } else { 4096 }),
1492	    limit,
1493	    truncated: false,
1494	    finished: false,
1495	  }
1496	}
