1637	fn process_error_type(output : String) -> String {
1638	  let text = output.to_lower()
1639	  if text.contains("out of memory") || text.contains("cannot allocate memory") {
1640	    "memory_exhausted"
1641	  } else if text.contains("no space left on device") {
1642	    "disk_exhausted"
1643	  } else if text.contains("address already in use") ||
1644	    text.contains("addrinuse") {
1645	    "address_in_use"
1646	  } else if text.contains("permission denied (publickey") ||
1647	    text.contains("authentication failed") {
1648	    "authentication_failed"
1649	  } else if text.contains("host key verification failed") {
1650	    "host_key_failed"
1651	  } else if text.contains("connection refused") {
1652	    "connection_refused"
1653	  } else if text.contains("connection timed out") ||
1654	    text.contains("operation timed out") {
1655	    "connection_timeout"
1656	  } else if text.contains("could not resolve hostname") {
1657	    "name_resolution"
1658	  } else if text.contains("controlsocket") || text.contains("control socket") {
1659	    "control_socket"
1660	  } else if text.contains("build_vm:") {
1661	    "vm_boot"
1662	  } else if text.contains("create microsandbox vm") && text.contains("network:") {
1663	    "vm_network"
1664	  } else if text.contains("create microsandbox vm") && text.contains("mount:") {
1665	    "vm_mount"
1666	  } else if text.contains("ensure microsandbox final image") ||
1667	    text.contains("prepare microsandbox final image") {
1668	    "vm_image"
1669	  } else if text.contains("create microsandbox vm") {
1670	    "vm_create"
1671	  } else if text.contains("start microsandbox vm") {
1672	    "vm_start"
1673	  } else if text.contains("no such file or directory") ||
1674	    text.contains("not found") {
1675	    "missing_resource"
1676	  } else if text.contains("permission denied") {
1677	    "permission_denied"
1678	  } else if text.contains("database is locked") ||
1679	    text.contains("database locked") {
1680	    "database_locked"
1681	  } else if text.contains("too many open files") {
1682	    "file_limit"
1683	  } else {
1684	    "process_exit"
1685	  }
1686	}
