1154	///|
1155	fn diagnostic_error(
1156	  error : Error,
1157	  environment? : Map[String, String],
1158	) -> String {
1159	  let (message, omitted) = match error {
1160	    AdapterError(detail) => (detail, false)
1161	    InvalidConfig(detail) => (detail, false)
1162	    SettingsProcessError(phase, code, status, detail) =>
1163	      (
1164	        "Orca settings process failed (exit \{status}, \{phase}: \{code})" +
1165	        detail.map(value => ":\n" + value).unwrap_or(""),
1166	        false,
1167	      )
1168	    @base64.Malformed(_) => ("Malformed base64 input; input omitted", true)
1169	    @utf8.Malformed(_) => ("Malformed UTF-8 input; input omitted", true)
1170	    @json.InvalidNumber(position, _) =>
1171	      (
1172	        "Invalid JSON number at line \{position.line}, column \{position.column}; value omitted",
1173	        true,
