1233	fn diagnostic_partial_secret(text : String, secrets : Array[String]) -> String {
1234	  let chars = text.iter().to_array()
1235	  let mut boundary = chars.length()
1236	  for secret in secrets {
1237	    let value = secret.iter().to_array()
1238	    if value.length() == 0 || text.has_suffix(secret) {
1239	      continue
1240	    }
1241	    let limit = if value.length() - 1 < boundary {
1242	      value.length() - 1
1243	    } else {
1244	      boundary
1245	    }
1246	    if limit == 0 {
1247	      continue
1248	    }
1249	    let prefixes = FixedArray::make(limit, 0)
1250	    let mut matched = 0
1251	    for index in 1..<limit {
1252	      while matched > 0 && value[matched] != value[index] {
1253	        matched = prefixes[matched - 1]
1254	      }
1255	      if value[matched] == value[index] {
1256	        matched += 1
1257	      }
1258	      prefixes[index] = matched
1259	    }
1260	    matched = 0
1261	    for index in 0..<boundary {
1262	      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
1263	        matched = prefixes[matched - 1]
1264	      }
1265	      if matched < limit && value[matched] == chars[index] {
1266	        matched += 1
1267	      }
1268	    }
1269	    boundary -= matched
1270	  }
1271	  if boundary == chars.length() {
1272	    text
1273	  } else {
1274	    character_text(chars, 0, boundary) + "[redacted]"
1275	  }
