+///|
+fn credential_argument(name : String) -> Bool {
+  let normalized = name.to_lower().replace_all(old="-", new="_")
+  !["_enabled", "_disabled", "_count", "_mode", "_method"]
+  .iter()
+  .any(suffix => normalized.has_suffix(suffix)) &&
+  credential_field(name, for_diagnostics=true)
