+///|
+fn up_arguments_evidence(
+  args : Array[String],
+  sources : Array[String],
+) -> (Json, Array[String], Bool) {
+  let secrets : Array[String] = []
+  for index, argument in args {
+    if argument.has_prefix("-") &&
+      credential_argument(argument) &&
+      !argument.contains("=") &&
+      index + 1 < args.length() {
+      add_protected_secret(secrets, args[index + 1])
+    }
+    if argument.split_once("=") is Some((name, value)) {
+      if credential_argument(name.to_owned()) {
+        add_protected_secret(secrets, value.to_owned())
+      } else if name == "--provider-option" &&
+        value.split_once("=") is Some((key, setting)) &&
+        credential_argument(key.to_owned()) {
+        add_protected_secret(secrets, setting.to_owned())
+      }
+    }
+    if secrets.length() > 512 {
+      return (
+        { "argumentCount": args.length(), "reason": "protected_value_limit" },
+        [],
+        true,
+      )
+    }
+  }
+  let arguments : Array[Json] = args.mapi((index, value) => {
+    "value": value,
+    "source": sources[index],
+  })
+  ({ "arguments": arguments }, secrets, false)
+}
