const result=await tools.exec_command({
 cmd:"python3 - <<'PY'
import json, os, shutil, signal, subprocess, tempfile, time
from pathlib import Path
root=Path('/Users/a13400/src/atty303/orca-env-devsy')
node=shutil.which('node') or shutil.which('bun')
if not node: print(json.dumps({'available':False})); raise SystemExit(0)
lines=(root/'src/server.mbt').read_text().splitlines()
helper='\n'.join(line.split('#|',1)[1] for line in lines[368:451] if '#|' in line)
with tempfile.TemporaryDirectory(prefix='orca-review-detach-') as tmp:
 tmp_path=Path(tmp)
 results={}
 for mode in ['direct','captured']:
  home=tmp_path/mode; cli=home/'.local/share/orca-env-devsy/orca/current/resources/app.asar/out/cli/index.js';cli.parent.mkdir(parents=True)
  marker=home/'survived'; pidfile=home/'pid'
  childcode='setTimeout(()=>{process.stderr.write("later diagnostic\\n"); setTimeout(()=>require("fs").writeFileSync(process.argv[1],"alive"),100);},800);'
  cli.write_text('const c=require("child_process").spawn(process.execPath,["-e",'+json.dumps(childcode)+','+json.dumps(str(marker))+'],{detached:true,stdio:["ignore","ignore","inherit"]});c.unref();require("fs").writeFileSync('+json.dumps(str(pidfile))+',String(c.pid));console.log("{}");')
  env={'HOME':str(home),'XDG_STATE_HOME':str(home/'state'),'PATH':'/usr/bin:/bin'}
  if mode=='direct':
   with open(os.devnull,'wb') as sink: p=subprocess.run([node,str(cli)],env=env,cwd=str(home),stdout=subprocess.PIPE,stderr=sink,timeout=4)
  else:
   p=subprocess.run([node,'-e',helper,'[]','{}','0','/tmp/project','ws://127.0.0.1:47121','','','fixture-run'],env=env,cwd=str(home),stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=4)
  pid=int(pidfile.read_text()) if pidfile.exists() else None
  deadline=time.monotonic()+2
  while time.monotonic()<deadline and not marker.exists(): time.sleep(.05)
