530	async fn diagnostic_retained_records(file : @fs.File, size : Int64) -> String {
531	  let length = if size > 262144L { 262144 } else { size.to_int() }
532	  let bytes = FixedArray::make(length, b'\x00')
533	  let read = file.read_at(bytes, position=size - length.to_int64())
534	  let text = @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:read])
535	  let lines = text.split("\n").to_array()
536	  let kept = FixedArray::make(lines.length(), false)
537	  let mut remaining = 65536
538	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
539	    if i == 0 && size > length.to_int64() {
540	      continue
541	    }
542	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
543	    let overhead = if field(event, "runId") is Some(Json::String(_)) {
544	      100
545	    } else {
546	      0
547	    }
548	    let length = lines[i].length() + 1 + overhead
549	    if length <= remaining {
550	      kept[i] = true
551	      remaining -= length
552	    }
553	  }
554	  remaining = 65536
555	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
556	    if kept[i] || (i == 0 && size > length.to_int64()) {
557	      continue
558	    }
559	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
560	    let failed = field(event, "errorType") is Some(_) ||
561	      (match field(event, "status") {
562	        Some(Json::String(status)) =>
563	          ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
564	            status,
565	          )
566	        _ => false
567	      })
568	    let overhead = if field(event, "runId") is Some(Json::String(_)) {
569	      100
570	    } else {
571	      0
572	    }
573	    let length = lines[i].length() + 1 + overhead
574	    if failed && length <= remaining {
575	      kept[i] = true
576	      remaining -= length
577	    }
578	  }
579	  let dropped_runs : Map[String, Bool] = Map([])
580	  for i in 0..<(lines.length() - 1) {
581	    if !kept[i] {
582	      let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
583	      if field(event, "runId") is Some(Json::String(id)) {
584	        dropped_runs.set(id, true)
585	      }
586	    }
587	  }
588	  let result = @buffer.Buffer(size_hint=131072)
589	  for i in 0..<lines.length() {
590	    if kept[i] {
591	      let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
592	      if field(event, "runId") is Some(Json::String(id)) {
593	        set_field(
594	          event,
595	          "runCompleteness",
596	          Json::string(
597	            if dropped_runs.contains(id) ||
598	              field(event, "runCompleteness") == Some(Json::string("partial")) {
599	              "partial"
600	            } else {
601	              "unknown"
602	            },
603	          ),
604	        )
605	        set_field(event, "runMissingReason", Json::string("retention_limit"))
606	        result.write_string_utf8(event.stringify() + "\n")
607	      } else {
608	        result.write_string_utf8(lines[i].to_owned() + "\n")
609	      }
610	    }
611	  }
